package dev.cammiescorner.arcanus.common.networking.serverbound;

import commonnetwork.networking.data.PacketContext;
import dev.cammiescorner.arcanus.Arcanus;
import dev.cammiescorner.arcanus.api.arcana.PrimalArcana;
import dev.cammiescorner.arcanus.api.spell.Pattern;
import dev.cammiescorner.arcanus.api.spell.Spell;
import dev.cammiescorner.arcanus.api.spell.components.SpellGroup;
import dev.cammiescorner.arcanus.common.data.ArcanusItemTags;
import dev.cammiescorner.arcanus.common.data_component.SpellBookComponent;
import dev.cammiescorner.arcanus.common.item.StaffItem;
import dev.cammiescorner.arcanus.common.registry.ArcanusAttributes;
import dev.cammiescorner.arcanus.common.registry.ArcanusComponents;
import dev.cammiescorner.arcanus.common.registry.ArcanusDataComponents;
import dev.cammiescorner.arcanus.common.util.ArcanusHelper;
import dev.emi.trinkets.api.TrinketComponent;
import dev.emi.trinkets.api.TrinketsApi;
import net.minecraft.ChatFormatting;
import net.minecraft.core.Holder;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.network.FriendlyByteBuf;
import net.minecraft.network.chat.Component;
import net.minecraft.network.codec.StreamCodec;
import net.minecraft.network.protocol.common.custom.CustomPacketPayload;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.item.Item;
import net.minecraft.world.item.ItemStack;

import java.util.ArrayList;
import java.util.List;
import java.util.Optional;

import static dev.cammiescorner.arcanus.common.util.TranslationKeys.*;

public record ServerboundSyncPatternPacket(List<Pattern> patterns, boolean castSpell) implements CustomPacketPayload {
	public static final CustomPacketPayload.Type<ServerboundSyncPatternPacket> TYPE = new CustomPacketPayload.Type<>(Arcanus.id("sync_pattern"));
	public static final StreamCodec<? extends FriendlyByteBuf, ServerboundSyncPatternPacket> CODEC = StreamCodec.of((buffer, packet) -> {
		buffer.writeCollection(packet.patterns, FriendlyByteBuf::writeEnum);
		buffer.writeBoolean(packet.castSpell);
	}, buffer -> {
		List<Pattern> patterns = buffer.readCollection(ArrayList::new, buf -> buf.readEnum(Pattern.class));
		boolean castSpell = buffer.readBoolean();

		return new ServerboundSyncPatternPacket(patterns, castSpell);
	});

	public static void handle(PacketContext<ServerboundSyncPatternPacket> context) {
		ServerPlayer player = context.sender();
		List<Pattern> pattern = context.message().patterns();

		ArcanusComponents.setPattern(player, pattern);

		if(pattern.size() >= 3 && context.message().castSpell()) {
			ItemStack stack = player.getMainHandItem();

			if(stack.getItem() instanceof StaffItem staff) {
				Optional<TrinketComponent> optional = TrinketsApi.getTrinketComponent(player);

				if(optional.isPresent()) {
					ItemStack spellBook = ArcanusHelper.getActiveSpellBook(player);
					SpellBookComponent spells = spellBook.getOrDefault(ArcanusDataComponents.SPELL_BOOK.get(), SpellBookComponent.empty());
					int index = ArcanusHelper.getSpellIndex(pattern);

					if(player.getCooldowns().getCooldownPercent(staff, 1f) == 0) {
						Spell spell = spells.getSpell(index);

						if(!spell.getComponentGroups().stream().flatMap(SpellGroup::getAllComponents).allMatch(spellComponent -> ArcanusComponents.knowsSpellComponents(player, spellComponent))) {
							player.displayClientMessage(Component.translatable(SPELL_UNKNOWN_SPELL_COMPONENTS).withStyle(ChatFormatting.RED, ChatFormatting.ITALIC), true);
							return;
						}

						if(spell.getComponentGroups().stream().flatMap(SpellGroup::getAllComponents).count() > ArcanusComponents.maxSpellSize()) {
							player.displayClientMessage(Component.translatable(SPELL_TOO_MANY_COMPONENTS), true);
							return;
						}

						for(PrimalArcana primalArcana : spell.getArcanaCost().keySet()) {
							if(!player.isCreative() && !ArcanusComponents.drainArcana(player, primalArcana, spell.getArcanaCost().getDouble(primalArcana), false)) {
								player.displayClientMessage(Component.translatable(SPELL_NOT_ENOUGH_MANA).withStyle(ChatFormatting.RED, ChatFormatting.ITALIC), true);
								return;
							}
						}

						ArcanusComponents.setPattern(player, ArcanusHelper.getSpellPattern(index));
						ArcanusComponents.setLastCastTime(player, player.level().getGameTime());
						spell.cast(player, player.serverLevel(), stack);
						player.displayClientMessage(Component.translatable(spell.getName()).withStyle(ChatFormatting.GREEN), true);

						for(Holder<Item> holder : BuiltInRegistries.ITEM.getTagOrEmpty(ArcanusItemTags.STAVES))
							player.getCooldowns().addCooldown(holder.value(), (int) (spell.getCoolDown() * player.getAttributeValue(ArcanusAttributes.SPELL_COOL_DOWN.holder())));
					}
				}
			}
		}
	}

	@Override
	public Type<? extends CustomPacketPayload> type() {
		return TYPE;
	}
}

package dev.cammiescorner.arcanus.api.spell;

import com.mojang.serialization.Codec;
import com.mojang.serialization.codecs.RecordCodecBuilder;
import dev.cammiescorner.arcanus.Arcanus;
import dev.cammiescorner.arcanus.ArcanusConfig;
import dev.cammiescorner.arcanus.api.arcana.PrimalArcana;
import dev.cammiescorner.arcanus.api.spell.components.SpellComponent;
import dev.cammiescorner.arcanus.api.spell.components.SpellGroup;
import dev.cammiescorner.arcanus.api.spell.components.SpellShape;
import dev.cammiescorner.arcanus.common.registry.ArcanusAttributes;
import dev.cammiescorner.arcanus.common.util.TranslationKeys;
import it.unimi.dsi.fastutil.objects.Object2DoubleArrayMap;
import net.minecraft.ChatFormatting;
import net.minecraft.network.RegistryFriendlyByteBuf;
import net.minecraft.network.chat.Component;
import net.minecraft.network.codec.ByteBufCodecs;
import net.minecraft.network.codec.StreamCodec;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.item.ItemStack;

import java.util.List;
import java.util.function.Predicate;
import java.util.stream.Stream;

public class Spell {
	public static final Codec<Spell> CODEC = RecordCodecBuilder.create(spellInstance -> spellInstance.group(
		Codec.list(SpellGroup.CODEC).optionalFieldOf("ComponentGroups", List.of(new SpellGroup(SpellShape.empty(), List.of(), List.of()))).forGetter(Spell::getComponentGroups),
		Codec.STRING.optionalFieldOf("Name", "Blank").forGetter(Spell::getName),
		SpellAspects.CODEC.optionalFieldOf("Aspects", new SpellAspects(1, 1, 1)).forGetter(Spell::getAspects)
	).apply(spellInstance, Spell::new));
	public static final StreamCodec<RegistryFriendlyByteBuf, Spell> STREAM_CODEC = StreamCodec.composite(
		SpellGroup.STREAM_CODEC.apply(ByteBufCodecs.list()), Spell::getComponentGroups,
		ByteBufCodecs.STRING_UTF8, Spell::getName,
		SpellAspects.STREAM_CODEC, Spell::getAspects,
		Spell::new
	);
	private final List<SpellGroup> groups;
	private final String name;
	private final SpellAspects aspects;

	public Spell(List<SpellGroup> groups, String name, SpellAspects aspects) {
		this.groups = groups;
		this.name = name;
		this.aspects = aspects;
	}

	public Spell() {
		this(List.of(new SpellGroup(SpellShape.empty(), List.of(), List.of())), "Blank", new SpellAspects(1, 1, 1));
	}

	public List<SpellGroup> getComponentGroups() {
		return groups;
	}

	public String getName() {
		return name;
	}

	public SpellAspects getAspects() {
		return aspects;
	}

	public boolean isEmpty() {
		return groups.isEmpty() || groups.get(0).isEmpty();
	}

	public Weight getWeight() {
		int averageWeightIndex = 0;

		if(!groups.isEmpty()) {
			int i = 0;

			for(SpellGroup group : groups) {
				if(group.isEmpty())
					continue;

				averageWeightIndex += group.getWeight().ordinal();
				i++;
			}

			averageWeightIndex = Math.round(averageWeightIndex / (float) i);
		}

		return Weight.values()[averageWeightIndex];
	}

	public Object2DoubleArrayMap<PrimalArcana> getArcanaCost() {
		Object2DoubleArrayMap<PrimalArcana> cumulativeArcanaCost = new Object2DoubleArrayMap<>();

		for(PrimalArcana primalArcana : cumulativeArcanaCost.keySet()) {
			for(SpellGroup group : groups)
				cumulativeArcanaCost.put(primalArcana, cumulativeArcanaCost.get(primalArcana) + group.getArcanaCost().get(primalArcana));

			cumulativeArcanaCost.put(primalArcana, cumulativeArcanaCost.get(primalArcana) * getArcanaMultiplier());
		}

		return cumulativeArcanaCost;
	}

	public double getArcanaMultiplier() {
		double arcanaModifier = 1;

		for(SpellGroup group : groups)
			arcanaModifier += group.shape().getArcanaModifier();

		return arcanaModifier;
	}

	public int getCoolDown() {
		int coolDown = Math.max(Math.toIntExact(components().count()) * ArcanusConfig.coolDownPerComponent, ArcanusConfig.minimumCoolDown);
		double coolDownModifier = 1d;

		if(!groups.isEmpty())
			for(SpellGroup group : groups)
				coolDownModifier *= group.shape().getCoolDownModifier();

		return (int) (coolDown * coolDownModifier);
	}

	public String getArcanaCostAsString(PrimalArcana primalArcana) {
		return Arcanus.format(getArcanaCost().getDouble(primalArcana));
	}

	public String getCoolDownAsString() {
		return Arcanus.format(getCoolDown() / 20d) + "s";
	}

	public Stream<SpellComponent> components() {
		return groups.stream().flatMap(SpellGroup::getAllComponents);
	}

	public void cast(LivingEntity caster, ServerLevel world, ItemStack stack) {
		List<SpellGroup> groups = getComponentGroups();

		if(groups.isEmpty())
			return;

		if(groups.stream().flatMap(SpellGroup::getAllComponents).anyMatch(Predicate.not(SpellComponent::isEnabled))) {
			caster.sendSystemMessage(Component.translatable(TranslationKeys.SPELL_HAS_DISABLED_COMPONENT).withStyle(ChatFormatting.RED));
			return;
		}

		// start casting the spell
		SpellGroup firstGroup = groups.getFirst();
		firstGroup.shape().cast(caster, caster.position(), null, world, stack, firstGroup.effects(), groups, 0, caster.getAttributeValue(ArcanusAttributes.SPELL_POTENCY.holder()));
	}
}

package dev.cammiescorner.arcanus.api.spell.components;

import com.mojang.datafixers.util.Pair;
import com.mojang.serialization.Codec;
import com.mojang.serialization.codecs.RecordCodecBuilder;
import dev.cammiescorner.arcanus.api.arcana.PrimalArcana;
import dev.cammiescorner.arcanus.api.spell.Weight;
import dev.cammiescorner.arcanus.common.registry.ArcanusSpellComponents;
import dev.cammiescorner.arcanus.common.util.XtraCodecs;
import it.unimi.dsi.fastutil.objects.Object2DoubleArrayMap;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.NbtOps;
import net.minecraft.network.RegistryFriendlyByteBuf;
import net.minecraft.network.codec.ByteBufCodecs;
import net.minecraft.network.codec.StreamCodec;
import org.joml.Vector2i;

import java.util.List;
import java.util.function.Function;
import java.util.stream.Stream;

public record SpellGroup(SpellShape shape, List<SpellEffect> effects, List<Vector2i> positions) {
	public static final Codec<SpellGroup> CODEC = RecordCodecBuilder.create(instance -> instance.group(
		SpellShape.CODEC.optionalFieldOf("Shape", SpellShape.empty()).forGetter(SpellGroup::shape),
		Codec.list(SpellEffect.CODEC).optionalFieldOf("Effects", List.of()).forGetter(SpellGroup::effects),
		Codec.list(XtraCodecs.VEC2I_CODEC).optionalFieldOf("Positions", List.of()).forGetter(SpellGroup::positions)
	).apply(instance, SpellGroup::new));
	public static final StreamCodec<RegistryFriendlyByteBuf, SpellGroup> STREAM_CODEC = StreamCodec.composite(
		SpellComponent.STREAM_CODEC.map(spellComponent -> (SpellShape) spellComponent, Function.identity()), SpellGroup::shape,
		SpellComponent.STREAM_CODEC.map(spellComponent -> (SpellEffect) spellComponent, Function.identity()).apply(ByteBufCodecs.list()), SpellGroup::effects,
		XtraCodecs.VEC2I_STREAM_CODEC.apply(ByteBufCodecs.list()), SpellGroup::positions,
		SpellGroup::new
	);

	public static SpellGroup fromNbt(CompoundTag tag) {
		return SpellGroup.CODEC.decode(NbtOps.INSTANCE, tag).result().orElseGet(() -> Pair.of(new SpellGroup(SpellShape.empty(), List.of(), List.of()), tag)).getFirst();
	}

	public CompoundTag toNbt() {
		CompoundTag tag = new CompoundTag();

		SpellGroup.CODEC.encode(this, NbtOps.INSTANCE, tag);

		return tag;
	}

	public Weight getWeight() {
		return shape.getWeight();
	}

	public Object2DoubleArrayMap<PrimalArcana> getArcanaCost() {
		Object2DoubleArrayMap<PrimalArcana> cumulativeArcanaCost = new Object2DoubleArrayMap<>(shape().getArcanaCost());

		for(SpellEffect effect : effects)
			for(PrimalArcana primalArcana : effect.getArcanaCost().keySet())
				cumulativeArcanaCost.put(primalArcana, effect.getArcanaCost().getDouble(primalArcana) + cumulativeArcanaCost.get(primalArcana));

		return cumulativeArcanaCost;
	}

	public Stream<SpellComponent> getAllComponents() {
		return Stream.concat(Stream.of(shape), effects.stream());
	}

	public boolean isEmpty() {
		return ArcanusSpellComponents.EMPTY.is(shape);
	}
}

package dev.cammiescorner.arcanus.common.item;

import dev.cammiescorner.arcanus.Arcanus;
import dev.cammiescorner.arcanus.common.data_component.StaffParts;
