import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.state.BlockState;

import java.util.List;

public class StaffItem extends Item {
	public StaffItem() {
		super(new Item.Properties().stacksTo(1).attributes(createAttributes()).component(ArcanusDataComponents.STAFF_PARTS.get(), StaffParts.defaultInstance()));
	}

	@Override
	public void appendHoverText(ItemStack stack, TooltipContext context, List<Component> tooltipComponents, TooltipFlag tooltipFlag) {
		if(stack.has(ArcanusDataComponents.STAFF_PARTS.get())) {
			var staffParts = stack.get(ArcanusDataComponents.STAFF_PARTS.get());
			var staffCore = staffParts.staffCore().get(ArcanusDataComponents.STAFF_CORE.get());
			var staffCap = staffParts.staffCap().get(ArcanusDataComponents.STAFF_CAP.get());

			staffCore.addToTooltip(context, tooltipComponents::add, tooltipFlag);
			staffCap.addToTooltip(context, tooltipComponents::add, tooltipFlag);
		}
	}

	@Override
	public boolean isEnchantable(ItemStack stack) {
		return true;
	}

	@Override
	public boolean canAttackBlock(BlockState state, Level level, BlockPos pos, Player player) {
		return !player.isCreative() && !ArcanusComponents.isCasting(player);
	}

	@Override
	public boolean hurtEnemy(ItemStack stack, LivingEntity target, LivingEntity attacker) {
		return true;
	}

	public static ItemAttributeModifiers createAttributes() {
		return ItemAttributeModifiers.builder()
			.add(Attributes.ATTACK_DAMAGE, new AttributeModifier(BASE_ATTACK_DAMAGE_ID, 4, AttributeModifier.Operation.ADD_VALUE), EquipmentSlotGroup.MAINHAND)
			.add(Attributes.ATTACK_SPEED, new AttributeModifier(BASE_ATTACK_SPEED_ID, -3, AttributeModifier.Operation.ADD_VALUE), EquipmentSlotGroup.MAINHAND)
			.add(Attributes.ENTITY_INTERACTION_RANGE, new AttributeModifier(Arcanus.id("staff_reach"), 0.5, AttributeModifier.Operation.ADD_VALUE), EquipmentSlotGroup.MAINHAND)
			.build();
	}
}

public void tick(CallbackInfo info) {
	if(player == null)
		return;

	ItemStack stack = player.getMainHandItem();

	if(timer == 0 || (lastMouseDown != null && !lastMouseDown.isDown()) || ArcanusComponents.isStunned(player)) {
		patterns.clear();
		Network.getNetworkHandler().sendToServer(new ServerboundSyncPatternPacket(patterns, false));
		lastMouseDown = null;
		isCasting = false;
		timer = 0;

		if(ArcanusComponents.isStunned(player))
			player.resetAttackStrengthTicker();
	}

	if(stack.getItem() instanceof StaffItem staff) {
		if(timer > 0 && patterns.size() >= 3) {
			isCasting = lastMouseDown != null && lastMouseDown.isDown();

			if(isCasting) {
				mouseDownTimer++;

				if(player.getCooldowns().getCooldownPercent(staff, getFrameTimeNs()) == 0) {
					Network.getNetworkHandler().sendToServer(new ServerboundSyncPatternPacket(patterns, true));
					timer = 20;
				}
			}
			else {
				timer = 0;
				mouseDownTimer = 0;
			}
		}
	}
	else {
		timer = 0;
	}

	if(isCasting() && !ArcanusComponents.isCasting(player) && mouseDownTimer > 5)
		Network.getNetworkHandler().sendToServer(new ServerboundIsCastingPacket(true));
	if(!isCasting() && ArcanusComponents.isCasting(player))
		Network.getNetworkHandler().sendToServer(new ServerboundIsCastingPacket(false));

	if(timer > 0 && player.getAttackStrengthScale(getFrameTimeNs()) == 1f && player.getCooldowns().getCooldownPercent(stack.getItem(), getFrameTimeNs()) == 0)
		timer--;
}

public void onLeftClick(CallbackInfo info) {
	if(isCasting)
		info.cancel();

	if(player != null && !player.isSpectator() && level != null) {
		if(player.getMainHandItem().getItem() instanceof StaffItem staff) {
			if(crosshairPickEntity != null && crosshairPickEntity.isAttackable())
				return;

			if(player.getAttackStrengthScale(getFrameTimeNs()) >= ((isLocalServer() ? ArcanusConfig.castingSpeedHasCoolDown : ArcanusClient.castingSpeedHasCoolDown) ? 1f : 0.15f) && player.getCooldowns().getCooldownPercent(staff, getFrameTimeNs()) == 0 && !isCasting) {
				timer = 30;
				patterns.add(Pattern.LEFT);
				Network.getNetworkHandler().sendToServer(new ServerboundSyncPatternPacket(patterns, false));
				player.swing(InteractionHand.MAIN_HAND);
				player.resetAttackStrengthTicker();
				player.level().playSeededSound(player, player.getX(), player.getY(), player.getZ(), SoundEvents.UI_BUTTON_CLICK, SoundSource.PLAYERS, 1f, 1.3f, 1L);

				if(patterns.size() >= 3)
					lastMouseDown = options.keyAttack;
			}
		}
		else {
			List<UUID> orbIds = player.getComponent(ArcanusComponents.STOCKPILE_ORB_COMPONENT).getOrbs();

			if(!orbIds.isEmpty()) {
				Network.getNetworkHandler().sendToServer(new ServerboundShootOrbsPacket(player.getUUID(), orbIds));
				shootOrbs(orbIds);
			}
		}
	}
}

public void onRightClick(CallbackInfo info) {
	if(isCasting)
		info.cancel();

	if(player != null && !player.isSpectator() && level != null && player.getMainHandItem().getItem() instanceof StaffItem staff) {
		if(hitResult != null && hitResult.getType() != HitResult.Type.MISS) {
			InteractionResult interactionResult = null;

			if(hitResult instanceof BlockHitResult blockHitResult && (!player.isCrouching() || (player.isCrouching() && level.getBlockState(blockHitResult.getBlockPos()).is(ArcanusBlocks.ARCANA_PIPE.get()))))
				interactionResult = gameMode.useItemOn(player, InteractionHand.MAIN_HAND, blockHitResult);
			if(hitResult instanceof EntityHitResult entityHitResult)
				interactionResult = gameMode.interactAt(player, entityHitResult.getEntity(), entityHitResult, InteractionHand.MAIN_HAND);

			if(interactionResult != null && interactionResult.consumesAction())
				return;
		}

		if(player.getAttackStrengthScale(getFrameTimeNs()) >= ((isLocalServer() ? ArcanusConfig.castingSpeedHasCoolDown : ArcanusClient.castingSpeedHasCoolDown) ? 1 : 0.15f) && player.getCooldowns().getCooldownPercent(staff, getFrameTimeNs()) == 0 && !isCasting) {
			timer = 30;
			patterns.add(Pattern.RIGHT);
			Network.getNetworkHandler().sendToServer(new ServerboundSyncPatternPacket(patterns, false));
			player.swing(InteractionHand.MAIN_HAND);
			player.resetAttackStrengthTicker();
			player.level().playSeededSound(player, player.getX(), player.getY(), player.getZ(), SoundEvents.UI_BUTTON_CLICK, SoundSource.PLAYERS, 1f, 1.1f, 1L);

			if(patterns.size() >= 3)
				lastMouseDown = options.keyUse;
		}
	}
}

package dev.cammiescorner.arcanus.common.networking.serverbound;

